CREATE TABLE [staging].[dimcustomer] ( [CustomerKey] int NULL, [GeographyKey] int NULL, [CustomerAlternateKey] varchar(8000) NULL, [Title] varchar(8000) NULL, [FirstName] varchar(8000) NULL, [MiddleName] varchar(8000) NULL, [LastName] varchar(8000) NULL, [NameStyle] bit NULL, [BirthDate] datetime2(6) NULL, [MaritalStatus] varchar(8000) NULL, [Suffix] varchar(8000) NULL, [Gender] varchar(8000) NULL, [EmailAddress] varchar(8000) NULL, [YearlyIncome] decimal(8,2) NULL, [TotalChildren] smallint NULL, [NumberChildrenAtHome] smallint NULL, [EnglishEducation] varchar(8000) NULL, [SpanishEducation] varchar(8000) NULL, [FrenchEducation] varchar(8000) NULL, [EnglishOccupation] varchar(8000) NULL, [SpanishOccupation] varchar(8000) NULL, [FrenchOccupation] varchar(8000) NULL, [HouseOwnerFlag] varchar(8000) NULL, [NumberCarsOwned] smallint NULL, [AddressLine1] varchar(8000) NULL, [AddressLine2] varchar(8000) NULL, [Phone] varchar(8000) NULL, [DateFirstPurchase] datetime2(6) NULL, [CommuteDistance] varchar(8000) NULL, [Inserted_at] datetime2(6)  NOT NULL, [Inserted_by] varchar(50) NOT NULL); 
CREATE TABLE [staging].[factinternetsales] ( [ProductKey] int NULL, [OrderDateKey] int NULL, [DueDateKey] int NULL, [ShipDateKey] int NULL, [CustomerKey] int NULL, [PromotionKey] int NULL, [CurrencyKey] int NULL, [SalesTerritoryKey] int NULL, [SalesOrderNumber] varchar(8000) NULL, [SalesOrderLineNumber] smallint NULL, [RevisionNumber] smallint NULL, [OrderQuantity] smallint NULL, [UnitPrice] decimal(6,2) NULL, [ExtendedAmount] decimal(6,2) NULL, [UnitPriceDiscountPct] float NULL, [DiscountAmount] float NULL, [ProductStandardCost] decimal(6,2) NULL, [TotalProductCost] decimal(6,2) NULL, [SalesAmount] decimal(6,2) NULL, [TaxAmt] decimal(5,2) NULL, [Freight] decimal(4,2) NULL, [CarrierTrackingNumber] varchar(8000) NULL, [CustomerPONumber] varchar(8000) NULL, [OrderDate] datetime2(6) NULL, [DueDate] datetime2(6) NULL, [ShipDate] datetime2(6) NULL, [Inserted_at] datetime2(6)  NOT NULL, [Inserted_by] varchar(50)  NOT NULL);

